ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "WSRequestHeader": {
    "System": {
      "name": vars.headers.name default "",
      "correlationID": vars.headers."X-CORRELATION-ID" default "",
      "processingServer": ""
    },
    "Property": [
    	{
        "Name": "CHANNEL",
        "Value": vars.parameters.ORIGIN default ""
      }
    ]
  },
  "WSRequestBody": {
    "Audit": {
      "Canal": vars.headers.name default ""
    },
    "Agrupation_Number": vars.parameters.AGRUPATION_NUMBER as Number default 0 ,
    "Name": vars.parameters.NAME default ""

    }
}

%dw 2.0 output application/json --- { codeResponse: vars.httpStatus as String, messageResponse: payload.WSResponseHeader.Service.statusDetail[0].errorDetailCode, "bag": { "id": payload.Id, "name": payload.Name, "description": payload.Description, "benefits": payload.Benefits, "channel": payload.Channel, "value": payload.Value, "valueStr": payload.Value_Str, "validity": payload.Validity, "instructions": payload.Instructions, "technicalConditions": payload.Technical_Conditions, "image": if (payload.Image != null) { "icon": payload.Image.Icon, "logo": payload.Image.Logo } else null, "tooltip": payload.Tooltip default []
}
}
